function initIdioma(){const n=document.getElementById("languageSelect");n&&n.addEventListener("change",()=>{const t=n.value;document.cookie=`lang=${t}; path=/; max-age=31536000; SameSite=Lax`;const e=new URL(window.location.href);e.searchParams.set("lang",t),window.location.href=e.toString()})}function getCurrentLang(){const n=document.cookie.match(/lang=([a-zA-Z-]+)/);return new URLSearchParams(window.location.search).get("lang")||n?.[1]||"es"}function addLangToLinks(){const n=getCurrentLang();n&&document.querySelectorAll('a[href^="/"]').forEach(t=>{const e=new URL(t.href,window.location.origin);e.searchParams.get("lang")!==n&&(e.searchParams.set("lang",n),t.href=e.pathname+e.search+e.hash)})}function interceptLinkClicks(){document.addEventListener("click",n=>{const t=n.target.closest("a");if(t&&t.href&&!t.href.startsWith("javascript:")&&!t.href.startsWith("#")&&t.href.startsWith(window.location.origin)){const e=getCurrentLang();if(e){const a=new URL(t.href);a.searchParams.get("lang")!==e&&(a.searchParams.set("lang",e),n.preventDefault(),window.location.href=a.toString())}}})}function updateFormActions(){const n=getCurrentLang();n&&document.querySelectorAll('form[action^="/"]').forEach(t=>{const e=new URL(t.action,window.location.origin);e.searchParams.get("lang")!==n&&(e.searchParams.set("lang",n),t.action=e.pathname+e.search)})}function initLangPersistence(){addLangToLinks(),interceptLinkClicks(),updateFormActions();new MutationObserver(()=>{addLangToLinks(),updateFormActions()}).observe(document.body,{childList:!0,subtree:!0})}export{initIdioma,addLangToLinks,getCurrentLang,interceptLinkClicks,updateFormActions,initLangPersistence};